using System.Linq;using System.Data.Entity;using System.Web.Mvc;using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Areas.Admin.Controllers { public class ProductsController:Controller { StoreContext db=new StoreContext(); protected override void OnActionExecuting(ActionExecutingContext c){if(Session["Role"]==null||Session["Role"].ToString()!="A"){c.Result=RedirectToAction("Login","Account",new{area=""});return;}base.OnActionExecuting(c);} public ActionResult Index(string q){var x=db.Products.Include(p=>p.Category).AsQueryable();if(!string.IsNullOrWhiteSpace(q))x=x.Where(p=>p.ProductName.Contains(q));ViewBag.Query=q;return View(x.OrderBy(p=>p.ProductName).ToList());} public ActionResult Create(){ViewBag.CategoryID=new SelectList(db.Categories,"CategoryID","CategoryName");return View("Form",new Product());} [HttpPost,ValidateAntiForgeryToken] public ActionResult Create(Product p){if(ModelState.IsValid){db.Products.Add(p);db.SaveChanges();return RedirectToAction("Index");}ViewBag.CategoryID=new SelectList(db.Categories,"CategoryID","CategoryName",p.CategoryID);return View("Form",p);} public ActionResult Edit(int id){var p=db.Products.Find(id);if(p==null)return HttpNotFound();ViewBag.CategoryID=new SelectList(db.Categories,"CategoryID","CategoryName",p.CategoryID);return View("Form",p);} [HttpPost,ValidateAntiForgeryToken] public ActionResult Edit(Product p){if(ModelState.IsValid){db.Entry(p).State=EntityState.Modified;db.SaveChanges();return RedirectToAction("Index");}ViewBag.CategoryID=new SelectList(db.Categories,"CategoryID","CategoryName",p.CategoryID);return View("Form",p);} public ActionResult Delete(int id){var p=db.Products.Find(id);if(p!=null){if(db.OrderDetails.Any(d=>d.ProductID==id))TempData["Error"]="Sản phẩm đã nằm trong đơn hàng, không thể xóa.";else{db.Products.Remove(p);db.SaveChanges();}}return RedirectToAction("Index");} } }